def compressir_repeticiones(texto: str) -> str:
    if not texto:
        return ""
    res = []
    i = 0
    n = len(texto)
    while i < n:
        ch = texto[i]
        j = i + 1
        while j < n and texto[j] == ch:
            j += 1
        count = j - i
        res.append(ch + str(count))
        i = j
    return ''.join(res)

def aplanar(datos):
    def _flatten(obj):
        if isinstance(obj, (list, tuple)):
            for item in obj:
                yield from _flatten(item)
        else:
            yield obj
    return list(_flatten(datos))

import csv
import io

def parsear_ventas(texto: str) -> list[dict]:
    if not texto or not texto.strip():
        return []

    reader = csv.reader(io.StringIO(texto))
    rows = list(reader)

    header = rows[0]
    expected_header = ['fecha', 'producto', 'cantidad', 'precio']
    if header != expected_header:
        raise ValueError("Header line does not match expected: fecha,producto,cantidad,precio")

    result = []
    for row in rows[1:]:
        # Skip empty lines (zero fields)
        if len(row) == 0:
            continue
        if len(row) != 4:
            raise ValueError(f"Row has {len(row)} fields, expected 4: {row}")

        fecha = row[0].strip()
        producto = row[1].strip()
        cantidad_str = row[2].strip()
        precio_str = row[3].strip()

        # Validate quantity
        try:
            cantidad = int(cantidad_str)
        except ValueError:
            raise ValueError(f"Cantidad '{cantidad_str}' is not an integer")
        if cantidad < 0:
            raise ValueError("Cantidad cannot be negative")

        # Validate price
        try:
            precio = float(precio_str)
        except ValueError:
            raise ValueError(f"Precio '{precio_str}' is not a number")

        result.append({
            'fecha': fecha,
            'producto': producto,
            'cantidad': cantidad,
            'precio': precio
        })

    return result

def promedio_movil(valores: list[float], ventana: int) -> list[float]:
    if ventana <= 0 or ventana > len(valores):
        return []
    resultado = []
    for i in range(len(valores) - ventana + 1):
        resultado.append(sum(valores[i:i+ventana]) / ventana)
    return resultado

def mochila(pesos: list[int], valores: list[int], capacidad: int) -> tuple[int, list[int]]:
    if len(pesos) != len(valores):
        raise ValueError("Lengths of pesos and valores must match")
    if any(p < 0 for p in pesos):
        raise ValueError("Negative weight found")
    if capacidad < 0:
        raise ValueError("Capacity cannot be negative")

    n = len(pesos)
    best = None
    for mask in range(1 << n):
        total_weight = 0
        total_value = 0
        indices = []
        for i in range(n):
            if mask & (1 << i):
                total_weight += pesos[i]
                total_value += valores[i]
                indices.append(i)
        if total_weight > capacidad:
            continue
        count = len(indices)
        idx_tuple = tuple(indices)  # already sorted because we added items in increasing order of index
        candidate = (total_value, total_weight, count, idx_tuple)
        if best is None:
            best = candidate
        else:
            cur_val, cur_wt, cur_cnt, cur_idx = best
            cand_val, cand_wt, cand_cnt, cand_idx = candidate
            if (cand_val > cur_val) or \
               (cand_val == cur_val and cand_wt < cur_wt) or \
               (cand_val == cur_val and cand_wt == cur_wt and cand_cnt < cur_cnt) or \
               (cand_val == cur_val and cand_wt == cur_wt and cand_cnt == cur_cnt and cand_idx < cur_idx):
                best = candidate
    if best is None:
        return (0, [])
    else:
        value, weight, count, idx_tuple = best
        return (value, list(idx_tuple))

def evaluar(expression: str) -> int:
    expr = expression.replace(" ", "")
    if '/' in expr or '**' in expr:
        raise ValueError
    try:
        result = eval(expr)
    except ZeroDivisionError:
        raise ZeroDivisionError
    except SyntaxError:
        raise ValueError
    except Exception:
        raise ValueError
    return int(result)

from collections import OrderedDict


class CacheLRU:
    def __init__(self, capacidad: int):
        if capacidad < 0:
            raise ValueError("Capacity cannot be negative")
        self.capacidad = capacidad
        self._datos = OrderedDict()

    def get(self, clave):
        if clave in self._datos:
            value = self._datos[clave]
            self._datos.move_to_end(clave, last=True)
            return value
        else:
            return None

    def put(self, clave, valor):
        if self.capacidad == 0:
            # No storage allowed when capacity is zero
            return
        if clave in self._datos:
            self._datos[clave] = valor
            self._datos.move_to_end(clave, last=True)
        else:
            if len(self._datos) >= self.capacidad:
                self._datos.popitem(last=False)
            self._datos[clave] = valor
            self._datos.move_to_end(clave, last=True)

    def __len__(self):
        return len(self._datos)
